package org.springframework.samples.petclinic.rest.advice;

/**
 * Thrown when a request to create an owner supplies a normalized telephone that is already
 * used by another owner. Carries the offending, normalized telephone so the exception handler
 * can report it, and lets the handler return a 409 Conflict.
 */
public class DuplicateOwnerTelephoneException extends RuntimeException {

    private final String telephone;

    public DuplicateOwnerTelephoneException(String telephone) {
        super("Telephone already in use by another owner: " + telephone);
        this.telephone = telephone;
    }

    public String getTelephone() {
        return this.telephone;
    }
}

