281	    /**
282	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city} or
283	     * {@code telephone} is missing or blank (including whitespace-only values that Bean Validation
284	     * does not catch). The names of all offending fields are collected so the caller receives a
285	     * 400 response whose {@code errors} array lists each one.
286	     */
287	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
288	        List<String> missingFields = new ArrayList<>();
289	        if (isBlank(ownerFieldsDto.getFirstName())) {
290	            missingFields.add("firstName");
291	        }
292	        if (isBlank(ownerFieldsDto.getLastName())) {
293	            missingFields.add("lastName");
294	        }
295	        if (isBlank(ownerFieldsDto.getAddress())) {
296	            missingFields.add("address");
297	        }
298	        if (isBlank(ownerFieldsDto.getCity())) {
299	            missingFields.add("city");
300	        }
301	        if (isBlank(ownerFieldsDto.getTelephone())) {
302	            missingFields.add("telephone");
303	        }
304	        if (!missingFields.isEmpty()) {
305	            throw new InvalidOwnerFieldsException(missingFields);
306	        }
