313	    /**
314	     * Normalizes an owner's {@code address} on create and writes the canonical form back onto the
315	     * request so it is what gets validated, compared, stored and returned. The value is trimmed,
316	     * runs of internal whitespace are collapsed to a single space, the result is upper-cased and
317	     * common street-type abbreviations are expanded as whole tokens ({@code ST}->{@code STREET},
318	     * {@code RD}->{@code ROAD}, {@code AVE}->{@code AVENUE}). Running before the required-field check
319	     * means an address that is blank after normalization is rejected like a missing one.
320	     */
321	    private void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
322	        ownerFieldsDto.setAddress(canonicalAddress(ownerFieldsDto.getAddress()));
323	    }
