325	    /**
326	     * Returns the canonical form of an address: trimmed, internal whitespace runs collapsed to a
327	     * single space, upper-cased, with common street-type abbreviations expanded as whole tokens. A
328	     * {@code null} value returns {@code null}. The transform is idempotent, so an already-canonical
329	     * address is returned unchanged, making it safe to apply to stored values during comparison.
330	     */
331	    private static String canonicalAddress(String address) {
332	        if (address == null) {
333	            return null;
334	        }
335	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
336	        if (collapsed.isEmpty()) {
337	            return "";
338	        }
339	        String[] tokens = collapsed.split(" ");
340	        StringBuilder sb = new StringBuilder(collapsed.length());
341	        for (int i = 0; i < tokens.length; i++) {
342	            if (i > 0) {
343	                sb.append(' ');
344	            }
345	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
346	        }
347	        return sb.toString();
348	    }
