350	    /**
351	     * Normalizes an owner's {@code telephone} on create into E.164 form. A leading {@code '+'} and
352	     * the country code that follows it are kept; otherwise the country code {@code '+61'} is assumed
353	     * and a single leading {@code '0'} is dropped from the national digits. Spaces, dashes and
354	     * brackets are stripped. The result must have 8 to 15 digits after the {@code '+'}. The E.164
355	     * string is written back onto the request so it is what gets stored and returned. Any value that
356	     * cannot form a valid E.164 number is rejected with a 400 response whose {@code errors} array
357	     * names {@code telephone}.
358	     */
359	    private void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
360	        ownerFieldsDto.setTelephone(toE164(ownerFieldsDto.getTelephone()));
361	    }
362	
363	    /**
364	     * Converts a raw telephone value to E.164 form, or throws {@link InvalidOwnerFieldsException}
365	     * (400) naming {@code telephone} when it cannot form a valid number.
366	     */
367	    private static String toE164(String telephone) {
368	        if (telephone == null) {
369	            throw new InvalidOwnerFieldsException(List.of("telephone"));
370	        }
371	        boolean hasCountryCode = telephone.trim().startsWith("+");
372	        String digits = telephone.replaceAll("\\D", "");
373	        String national;
374	        if (hasCountryCode) {
375	            national = digits;
376	        } else {
377	            if (digits.startsWith("0")) {
378	                digits = digits.substring(1);
379	            }
380	            national = "61" + digits;
381	        }
382	        if (!national.matches("[0-9]{8,15}")) {
383	            throw new InvalidOwnerFieldsException(List.of("telephone"));
384	        }
385	        return "+" + national;
386	    }
