388	    /**
389	     * Rejects creating an owner whose E.164 telephone is already used by any other owner. The
390	     * incoming value has already been converted to its E.164 form by {@link #normalizeTelephone};
391	     * each existing owner's stored telephone is converted the same way before comparison so numbers
392	     * that only differ in formatting still collide. A match results in a 409 response naming
393	     * {@code telephone}.
394	     */
395	    private void rejectDuplicateTelephone(OwnerFieldsDto ownerFieldsDto) {
396	        String telephone = ownerFieldsDto.getTelephone();
397	        for (Owner existing : this.clinicService.findAllOwners()) {
398	            if (telephone.equals(normalizeExisting(existing.getTelephone()))) {
399	                throw new DuplicateOwnerTelephoneException(telephone);
400	            }
401	        }
402	    }
403	
404	    /**
405	     * Returns the E.164 form of an already-stored telephone for duplicate comparison, or {@code null}
406	     * when the stored value cannot form a valid E.164 number (so it never matches an incoming one).
407	     */
408	    private static String normalizeExisting(String telephone) {
409	        try {
410	            return toE164(telephone);
411	        } catch (InvalidOwnerFieldsException ex) {
412	            return null;
413	        }
414	    }
