416	    /**
417	     * Rejects creating an owner whose {@code lastName} and {@code address} already belong to another
418	     * owner. Both fields are compared case-insensitively and with runs of whitespace collapsed to a
419	     * single space, so values that differ only in letter case or spacing still collide. When the
420	     * request opts in with {@code sharesHousehold} set to {@code true} the check is skipped, allowing
421	     * household members to share a name and address. A match results in a 409 response naming
422	     * {@code lastName} and {@code address}.
423	     */
424	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
425	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
426	            return;
427	        }
428	        String lastName = normalizeForComparison(ownerFieldsDto.getLastName());
429	        String address = canonicalAddress(ownerFieldsDto.getAddress());
430	        for (Owner existing : this.clinicService.findAllOwners()) {
431	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
432	                && address.equals(canonicalAddress(existing.getAddress()))) {
433	                throw new DuplicateOwnerHouseholdException(
434	                    ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
435	            }
436	        }
437	    }
