439	    /**
440	     * Rejects creating an owner in a city that has reached capacity: a city that already contains
441	     * {@value #MAX_OWNERS_PER_CITY} or more owners cannot take another one. Existing owners are
442	     * counted with a case-insensitive match on {@code city}, the same way {@link #assignCustomerCode}
443	     * groups a city. A city at or over the limit results in a 409 response naming {@code city}.
444	     */
445	    private void rejectCityAtCapacity(OwnerFieldsDto ownerFieldsDto) {
446	        String city = ownerFieldsDto.getCity();
447	        int count = 0;
448	        for (Owner existing : this.clinicService.findAllOwners()) {
449	            if (city.equalsIgnoreCase(existing.getCity())) {
450	                count++;
451	            }
452	        }
453	        if (count >= MAX_OWNERS_PER_CITY) {
454	            throw new OwnerCityAtCapacityException(city);
455	        }
456	    }
