458	    /**
459	     * Rejects creating an owner once {@value #MAX_OWNERS_PER_DAY} or more owners already carry the
460	     * given adjusted business-day {@code registrationDate}, counted by an exact match. The date has
461	     * already been resolved and rolled forward off a weekend by {@link #resolveRegistrationDate}, so
462	     * the limit is enforced per business day. A day at or over the limit results in a 429 response.
463	     */
464	    private void rejectDailyLimitReached(LocalDate registrationDate) {
465	        int count = 0;
466	        for (Owner existing : this.clinicService.findAllOwners()) {
467	            if (registrationDate.equals(existing.getRegistrationDate())) {
468	                count++;
469	            }
470	        }
471	        if (count >= MAX_OWNERS_PER_DAY) {
472	            throw new DailyOwnerLimitReachedException(registrationDate);
473	        }
474	    }
