476	    /**
477	     * Normalizes a value for case-insensitive, whitespace-insensitive comparison: leading and
478	     * trailing whitespace is trimmed, internal runs of whitespace are collapsed to a single space and
479	     * the result is lower-cased. A {@code null} value normalizes to the empty string.
480	     */
481	    private static String normalizeForComparison(String value) {
482	        if (value == null) {
483	            return "";
484	        }
485	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
486	    }
