488	    /**
489	     * Normalizes an owner's optional {@code email}. The field may be omitted entirely, but when a
490	     * value is present it must be a syntactically valid address; the trimmed value is lower-cased and
491	     * written back onto the request so that is what gets stored and returned. A present but invalid
492	     * address is rejected with a 400 response whose {@code errors} array names {@code email}.
493	     */
494	    private void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
495	        String email = ownerFieldsDto.getEmail();
496	        if (email == null) {
497	            return;
498	        }
499	        String trimmed = email.trim();
500	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
501	            throw new InvalidOwnerFieldsException(List.of("email"));
502	        }
503	        ownerFieldsDto.setEmail(trimmed.toLowerCase(Locale.ROOT));
504	    }
