506	    /**
507	     * Resolves an owner's effective {@code registrationDate} on create and rolls it onto a business
508	     * day. When the caller supplies no value it defaults to the server's current date; a value
509	     * provided in the request is kept. The effective date, whether supplied or defaulted, must fall
510	     * on a business day: a Saturday or Sunday is rolled forward to the following Monday. The adjusted
511	     * date is written back onto the request so it is what gets stored and returned (in ISO
512	     * {@code YYYY-MM-DD} format) and what every value derived from the registration date is based on.
513	     */
514	    private void resolveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
515	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
516	        if (effective == null) {
517	            effective = LocalDate.now();
518	        }
519	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
520	    }
