522	    /**
523	     * Rolls a date forward onto a business day: a Saturday or Sunday is advanced to the following
524	     * Monday; a weekday is returned unchanged.
525	     */
526	    private static LocalDate toBusinessDay(LocalDate date) {
527	        return switch (date.getDayOfWeek()) {
528	            case SATURDAY -> date.plusDays(2);
529	            case SUNDAY -> date.plusDays(1);
530	            default -> date;
531	        };
532	    }
