534	    /**
535	     * Assigns the owner's {@code customerCode} on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
536	     * where {@code CITY3} is the upper-cased first three letters of {@code city}, {@code LAST3} is the
537	     * upper-cased first three letters of {@code lastName} and {@code NNNN} is a per-city 4-digit
538	     * zero-padded sequence equal to one more than the number of owners already in that city
539	     * (e.g. {@code 'SYD-SMI-0007'}).
540	     */
541	    private void assignCustomerCode(Owner owner) {
542	        String city = owner.getCity();
543	        String lastName = owner.getLastName();
544	        String cityPrefix = city.substring(0, Math.min(3, city.length())).toUpperCase(Locale.ROOT);
545	        String lastPrefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
546	        int sequence = 1;
547	        for (Owner existing : this.clinicService.findAllOwners()) {
548	            if (city.equalsIgnoreCase(existing.getCity())) {
549	                sequence++;
550	            }
551	        }
552	        owner.setCustomerCode(String.format("%s-%s-%04d", cityPrefix, lastPrefix, sequence));
553	    }
