555	    /**
556	     * Assigns the owner's {@code membershipNumber} on create, formatted
557	     * {@code '<customerCode>-M<YY>'} where {@code YY} is the last two digits of the
558	     * {@code registrationDate} year (e.g. {@code 'SMI-0007-M26'}). Assigned after
559	     * {@link #assignCustomerCode} and once {@code registrationDate} has been defaulted, so both
560	     * inputs are present.
561	     */
562	    private void assignMembershipNumber(Owner owner) {
563	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
564	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
565	    }
