567	    /**
568	     * Assigns the new owner's {@code namesakeCount} on create: the number of owners that already
569	     * exist sharing the same {@code firstName} and {@code lastName}, compared case-insensitively.
570	     * Computed before the new owner is persisted, so it counts only the pre-existing owners.
571	     */
572	    private void assignNamesakeCount(Owner owner) {
573	        String firstName = owner.getFirstName();
574	        String lastName = owner.getLastName();
575	        int count = 0;
576	        for (Owner existing : this.clinicService.findAllOwners()) {
577	            if (firstName.equalsIgnoreCase(existing.getFirstName())
578	                && lastName.equalsIgnoreCase(existing.getLastName())) {
579	                count++;
580	            }
581	        }
582	        owner.setNamesakeCount(count);
583	    }
