585	    /**
586	     * Assigns the new owner's {@code membershipLevel} on create: a number from 1 to 3 starting at
587	     * 1, plus 1 when an email is present, plus 1 when {@code namesakeCount} is 0, capped at 3.
588	     * Level 4 is reserved for tenure. Runs after {@link #assignNamesakeCount} so that count is
589	     * settled.
590	     */
591	    private void assignMembershipLevel(Owner owner) {
592	        int level = 1;
593	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
594	            level++;
595	        }
596	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
597	            level++;
598	        }
599	        owner.setMembershipLevel(Math.min(level, 3));
600	    }
