602	    /**
603	     * Assigns the new owner's {@code bulkSignupWarning} on create: {@code true} when more than
604	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry the new owner's adjusted
605	     * business-day {@code registrationDate}, otherwise {@code false}. Counted the same way as the
606	     * daily-limit rule and computed before the new owner is persisted, so it counts only the
607	     * pre-existing owners for that day.
608	     */
609	    private void assignBulkSignupWarning(Owner owner) {
610	        LocalDate registrationDate = owner.getRegistrationDate();
611	        int count = 0;
612	        for (Owner existing : this.clinicService.findAllOwners()) {
613	            if (registrationDate.equals(existing.getRegistrationDate())) {
614	                count++;
615	            }
616	        }
617	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
618	    }
