620	    /**
621	     * Assigns the new owner's {@code householdId} when the request opts in with
622	     * {@code sharesHousehold} set to {@code true} and at least one existing owner already shares the
623	     * same last name and address (compared case-insensitively with runs of whitespace collapsed, the
624	     * same way {@link #rejectDuplicateHousehold} matches). The household's members and the new owner
625	     * all end up carrying one stable shared identifier: if any existing member already has a
626	     * {@code householdId} it is reused, otherwise a new one is derived from the normalized last name
627	     * and address. Any existing member that is missing the identifier is updated so the whole
628	     * household stays consistent. When the flag is absent, or set but no matching owner exists, no
629	     * identifier is assigned.
630	     */
631	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
632	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
633	            return;
634	        }
635	        String lastName = normalizeForComparison(owner.getLastName());
636	        String address = canonicalAddress(owner.getAddress());
637	        List<Owner> members = new ArrayList<>();
638	        for (Owner existing : this.clinicService.findAllOwners()) {
639	            if (lastName.equals(normalizeForComparison(existing.getLastName()))
640	                && address.equals(canonicalAddress(existing.getAddress()))) {
641	                members.add(existing);
642	            }
643	        }
644	        if (members.isEmpty()) {
645	            return;
646	        }
647	        String householdId = members.stream()
648	            .map(Owner::getHouseholdId)
649	            .filter(id -> id != null && !id.isBlank())
650	            .findFirst()
651	            .orElseGet(() -> newHouseholdId(lastName, address));
652	        owner.setHouseholdId(householdId);
653	        for (Owner member : members) {
654	            if (!householdId.equals(member.getHouseholdId())) {
655	                member.setHouseholdId(householdId);
656	                this.clinicService.saveOwner(member);
657	            }
658	        }
659	    }
660	
661	    /**
662	     * Assigns the new owner's {@code householdMemberCount} on create: the number of owners sharing
663	     * the new owner's {@code householdId} once this create is applied — that is, the new owner plus
664	     * every existing owner already carrying the same identifier. Runs after {@link #assignHousehold}
665	     * so the identifier is settled. Left {@code null} when the owner belongs to no household.
666	     */
667	    private void assignHouseholdMembership(Owner owner) {
668	        String householdId = owner.getHouseholdId();
669	        if (householdId == null || householdId.isBlank()) {
670	            owner.setHouseholdMemberCount(null);
671	            return;
672	        }
673	        int count = 1;
674	        for (Owner existing : this.clinicService.findAllOwners()) {
675	            if (householdId.equals(existing.getHouseholdId())) {
676	                count++;
677	            }
678	        }
679	        owner.setHouseholdMemberCount(count);
680	    }
681	
682	    /**
683	     * Derives a stable household identifier from the normalized last name and address: the first
684	     * twelve upper-case hex characters of the SHA-256 digest of {@code "<lastName>|<address>"}. Two
685	     * owners in the same household therefore derive the same value regardless of creation order.
686	     */
687	    private static String newHouseholdId(String normalizedLastName, String normalizedAddress) {
688	        try {
689	            byte[] digest = MessageDigest.getInstance("SHA-256")
690	                .digest((normalizedLastName + "|" + normalizedAddress).getBytes(StandardCharsets.UTF_8));
691	            StringBuilder hex = new StringBuilder(digest.length * 2);
692	            for (byte b : digest) {
693	                hex.append(String.format("%02x", b));
694	            }
695	            return hex.substring(0, 12).toUpperCase(Locale.ROOT);
696	        } catch (NoSuchAlgorithmException ex) {
697	            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
698	        }
699	    }
700	}
