238	    /**
239	     * Handles exception thrown by Bean Validation on controller methods parameters
240	     *
241	     * @param e The {@link MethodArgumentNotValidException} to be handled
242	     * @param request {@link HttpServletRequest} object referring to the current request.
243	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
244	     */
245	    @ExceptionHandler(MethodArgumentNotValidException.class)
246	    @ResponseBody
247	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
248	        HttpStatus status = HttpStatus.BAD_REQUEST;
249	        BindingErrorsResponse errors = new BindingErrorsResponse();
250	        BindingResult bindingResult = e.getBindingResult();
251	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
252	        if (bindingResult.hasErrors()) {
253	            errors.addAllErrors(bindingResult);
254	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
255	                .map(FieldError::getField)
256	                .distinct()
257	                .toList();
258	            detail.setProperty("errors", invalidFields);
259	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
260	                .map(fieldError -> {
261	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
262	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
263	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
264	                        fieldError.getField(),
265	                        defaultMessage,
266	                        rejectedValue);
267	                    return new ValidationMessageDto(message)
268	                        .putAdditionalProperty("field", fieldError.getField())
269	                        .putAdditionalProperty("rejectedValue", rejectedValue)
270	                        .putAdditionalProperty("defaultMessage", defaultMessage);
271	                })
272	                .toList();
273	            logger.debug("Validation error at {} {}: {}",
274	                request.getMethod(),
275	                request.getRequestURI(),
276	                bindingResult.getFieldErrors());
277	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
278	            return ResponseEntity.status(status).body(detail);
279	        }
280	        return ResponseEntity.status(status).body(detail);
281	    }
